// Parse the MediFind order.created payload
const payload = $input.first().json;
const data = payload.data || payload;

const isEmergency = data.isEmergency === true;
const urgencyBadge = isEmergency ? '🚨 EMERGENCY ORDER' : '🛒 New Order';
const items = (data.items || []).map(i => `  • ${i.inventoryId || 'Medicine'} × ${i.quantity}`).join('\n');

return [{
  json: {
    subject: `${urgencyBadge} — ${data.trackingNumber}`,
    body: `A new MediFind order has been placed.\n\n` +
          `Tracking: ${data.trackingNumber}\n` +
          `Customer: ${data.userName} (${data.userEmail})\n` +
          `Total: ₹${data.totalAmount?.toFixed(2) || '0.00'}\n` +
          `Payment: ${data.paymentMethod}\n` +
          `Delivery To: ${data.deliveryAddress || 'Not provided'}\n\n` +
          `Items (${data.itemCount || 0}):\n${items || '  (none)'}\n\n` +
          `${isEmergency ? '⚠️ This is a PRIORITY/EMERGENCY order requiring immediate attention.' : ''}\n\n` +
          `Placed at: ${payload.timestamp}`,
    isEmergency,
    orderId: data.orderId,
    trackingNumber: data.trackingNumber,
    userEmail: data.userEmail,
    totalAmount: data.totalAmount
  }
}];
